#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace FileCompass {
 internal static class ConflictUxTests {
  static void Place(Window w){w.WindowStartupLocation=WindowStartupLocation.Manual;w.Left=-18000;w.Top=-18000;w.ShowActivated=false;w.ShowInTaskbar=false;}
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();string motif=AppearanceTheme.Motif;Action<bool,string> check=(yes,text)=>{if(!yes)throw new Exception(text);checks.Add(text);};try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));L.ChangeLanguage("cs");FluentTheme.Ensure();AppearanceTheme.Apply("Light");
   var conflict=new CopyConflict{Source=@"F:\Moje Filmy\Erik the Viking (1989) AMIABLE.mkv",Target=@"E:\Temp\Moje Filmy\Erik the Viking (1989) AMIABLE.mkv",SourceSize=685681412,TargetSize=685681412,SourceTime=new DateTime(2019,7,31,20,10,0),TargetTime=new DateTime(2019,7,31,20,10,0)};
   foreach(string style in new[]{"Original","Balanced"}){AppearanceTheme.SetMotif(style);var preview=new CopyConflictDialog(null,conflict);Place(preview);preview.Show();NavigationTests.Wait(Task.Delay(120));preview.UpdateLayout();
    check(FluentUiTests.Children<GroupBox>(preview).Count()==2,style+": existing and incoming files have separate comparison cards");check(FluentUiTests.Children<TextBlock>(preview).Any(x=>x.Text==L.Text("conflict.sameMetadata")),style+": equal size and date do not imply equal content");check(!FluentUiTests.Children<Expander>(preview).Any(),style+": conflict has no expanding sections");var nav=FluentUiTests.Children<ListBox>(preview).Single();check(nav.Items.Count==2&&nav.SelectedIndex==0,style+": sidebar starts on basic actions");foreach(string key in new[]{"action.rename","action.append","action.overwrite","action.skip"})check(FluentUiTests.Children<Button>(preview).Any(x=>(string)x.Content==L.Text(key)&&x.IsVisible),style+": action immediately visible: "+key);double height=preview.ActualHeight;
    NextStageTests.Draw(preview,Path.Combine(root,style+"-conflict.png"));nav.SelectedIndex=1;NavigationTests.Wait(Task.Delay(180));preview.UpdateLayout();check(Math.Abs(preview.ActualHeight-height)<1,style+": sidebar switching preserves dialog height");check(FluentUiTests.Children<Button>(preview).Any(x=>(string)x.Content==L.Text("conflict.overwriteOlder")&&x.IsVisible),style+": bulk rule visible on rules page");NextStageTests.Draw(preview,Path.Combine(root,style+"-conflict-details.png"));preview.Close();
    foreach(bool all in new[]{false,true})foreach(bool overwrite in new[]{false,true}){var expected=overwrite?(all?CopyChoice.OverwriteAll:CopyChoice.Overwrite):(all?CopyChoice.SkipAll:CopyChoice.Skip);var result=Answer(conflict,all,overwrite?"action.overwrite":"action.skip",false);check(result.Choice==expected,style+": explicit scope returns "+expected);}
    foreach(var pair in new[]{Tuple.Create("conflict.overwriteOlder",CopyChoice.Older),Tuple.Create("conflict.overwriteDifferentSizeOrTime",CopyChoice.Different),Tuple.Create("conflict.overwriteIfSourceLarger",CopyChoice.Larger),Tuple.Create("conflict.overwriteIfSourceSmaller",CopyChoice.Smaller),Tuple.Create("conflict.autoRenameAll",CopyChoice.RenameAll)})check(Answer(conflict,false,pair.Item1,true).Choice==pair.Item2,style+": advanced rule preserves "+pair.Item2);
    check(Answer(conflict,true,"conflict.stopTask",false).Choice==CopyChoice.Cancel,style+": stopping cancels even with bulk scope selected");
    conflict.IsReadOnly=true;check(Answer(conflict,false,"action.overwrite",false,true).AllowReadOnly,style+": read-only permission is forwarded");conflict.IsReadOnly=false;
    conflict.TargetDirectory=true;var mismatch=new CopyConflictDialog(null,conflict);Place(mismatch);mismatch.Show();mismatch.UpdateLayout();check(!FluentUiTests.Children<Button>(mismatch).Single(x=>(string)x.Content==L.Text("action.overwrite")).IsEnabled,style+": file-folder collisions cannot be overwritten");mismatch.Close();conflict.TargetDirectory=false;
   }
   File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{AppearanceTheme.SetMotif(motif);}}
  static CopyDecision Answer(CopyConflict conflict,bool all,string key,bool advanced,bool readOnly=false){var w=new CopyConflictDialog(null,conflict);Place(w);Exception error=null;w.Loaded+=delegate{w.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(delegate{try{w.ApplyToAll.IsChecked=all;if(readOnly)FluentUiTests.Children<CheckBox>(w).Single(x=>(string)x.Content==L.Text("conflict.allowReadOnlyOverwriteForJob")).IsChecked=true;if(advanced)FluentUiTests.Children<ListBox>(w).Single().SelectedIndex=1;w.UpdateLayout();string label=L.Text(key);if(all&&key=="action.overwrite")label=L.Text("conflict.overwriteAll");if(all&&key=="action.skip")label=L.Text("conflict.skipAll");var buttons=FluentUiTests.Children<Button>(w).Where(x=>(string)x.Content==label).ToArray();var button=advanced?buttons.Single():buttons.First(x=>x.Parent is StackPanel);button.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}catch(Exception ex){error=ex;w.Close();}}));};w.ShowDialog();if(error!=null)throw error;return w.Decision;}
 }
}
#endif
